// Rust translation of soc/codecs/mt6359.h.
// C header guards and include directives are omitted.

pub const fn BIT(n: u32) -> u32 {
    1u32 << n
}

#[repr(C)]
pub struct device {
    _unused: [u8; 0],
}

#[repr(C)]
pub struct regmap {
    _unused: [u8; 0],
}

#[repr(C)]
pub struct snd_soc_component {
    _unused: [u8; 0],
}

