pub fn IS_DCC_BASE(type_: u32) -> bool {
    type_ == MIC_TYPE_MUX_DCC || type_ == MIC_TYPE_MUX_DCC_ECM_DIFF || type_ == MIC_TYPE_MUX_DCC_ECM_SINGLE
}
